 const ov=cl((xs-Z[3]+200)/500,0,1)*cl((Z[4]-xs+100)/500,0,1)*.28;if(ov>.01){g.fillStyle='rgba(120,128,136,'+ov+')';g.fillRect(0,0,480,GT+4)}
 const sn=cl((xs-Z[5]+200)/500,0,1)*cl((Z[6]-xs+200)/500,0,1)*.3;if(sn>.01){g.fillStyle='rgba(215,222,230,'+sn+')';g.fillRect(0,0,480,GT+4)}
